      INSERT INTO character_details (character_id, detail_json)
      VALUES (2073, '{"characterId":2073,"captainAbility":"<b>Always Active: </b>Boosts HP of all characters by 1.25x, boosts chances of getting [STR], [QCK], [PSY] orbs.. <b>Gear 2 Captain: </b>Boosts ATK of all characters by 3x, slightly boosts chances of getting [RCV] orbs and makes [QCK] orbs beneficial for all characters. <b>Gear 3 Captain: </b>Boosts ATK of all characters by 3.5x after 2 consecutive PERFECTs, boosts chances of getting [RCV] orbs and makes [STR] orbs beneficial for all characters. <b>Gear 4 - Boundman Captain: </b>Boosts ATK of all characters by 4x, reduces damage received by 20%, boosts chances of getting [RCV] orbs and makes [STR], [QCK] and [PSY] orbs beneficial for all characters. <b>Gear 4 - Tankman Captain: </b>Boosts ATK of this character by 4.25x, boosts ATK of all other characters by 4x, reduces damage received by 50% and makes [STR], [QCK] and [PSY] orbs beneficial for all characters. <b>Action: </b>Based on how full Gear Power Gauge is, transforms Luffy. If Gear Power is above 50%, changes between Gear 2 and Gear 3. If Gear Power is full, changes into Gear 4 - Boundman. This can be used an unlimited number of times per turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"<b>Always Active: </b>Boosts HP of all characters by 1.25x, boosts chances of getting [STR], [QCK], [PSY] orbs.. <b>Gear 2 Captain: </b>Boosts ATK of all characters by 3x, slightly boosts chances of getting [RCV] orbs and makes [QCK] orbs beneficial for all characters. <b>Gear 3 Captain: </b>Boosts ATK of all characters by 3.5x after 2 consecutive PERFECTs, boosts chances of getting [RCV] orbs and makes [STR] orbs beneficial for all characters. <b>Gear 4 - Boundman Captain: </b>Boosts ATK of all characters by 4x, reduces damage received by 20%, boosts chances of getting [RCV] orbs and makes [STR], [QCK] and [PSY] orbs beneficial for all characters. <b>Gear 4 - Tankman Captain: </b>Boosts ATK of this character by 4.25x, boosts ATK of all other characters by 4x, reduces damage received by 50% and makes [STR], [QCK] and [PSY] orbs beneficial for all characters. <b>Action: </b>Based on how full Gear Power Gauge is, transforms Luffy. If Gear Power is above 50%, changes between Gear 2 and Gear 3. If Gear Power is full, changes into Gear 4 - Boundman. This can be used an unlimited number of times per turn."}],"captainNotes":"In order to increase Gear Power Gauge level, you must hit a PERFECT with Luffy or consume [RCV] orbs. MAX Gear Power Gauge level is 8. Hitting a PERFECT with Luffy and consuming a [RCV] orb increases Gauge level by 1. If Luffy gets swapped out in battle, Gear Gauge Power will go to 0. While in Gear 4, Luffy will stay in that form until Gauge Power goes to 0. Attacking with any character while in Gear 4 reduces Gear Power Gauge by 3.","specialName":"Gomu Gomu no Kong Organ","specialText":"Deals 150x character''s ATK in Typeless damage to all enemies, boosts ATK of all characters by 2x for 1 turn, makes [RCV] and [TND] orbs beneficial for all characters for 3 turns. If Luffy is Captain or Friend/Guest Captain, transform into Gear 4","specialNotes":"If you use this special after consuming 10 [RCV] orbs since the start of the fight, transform into Tankman, otherwise transform into Boundman","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["monkey d. luffy","luffy"],"builderAbilities":[],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"ability":[{"effects":[{"attributes":["ATK"],"condition":{"comparator":"first","count":60,"type":"time"},"effect":"buff","level":2,"targeting":{"targets":["crew"]}}]},{"effects":[{"override":{"level":3}}]},{"effects":[{"override":{"level":4}}]},{"effects":[{"override":{"level":5}}]},{"effects":[{"override":{"level":6}}]}],"gpability":[{"effects":[{"a