      INSERT INTO character_details (character_id, detail_json)
      VALUES (2232, '{"characterId":2232,"captainAbility":"Reduces HP of all characters by 20%, reduces damage received by 13%, boosts chances of getting [RCV] orbs, makes [RCV] orbs beneficial for all characters, boosts ATK of all characters by 2x-3.75x depending on the amount healed in the last turn.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Reduces HP of all characters by 20%, reduces damage received by 13%, boosts chances of getting [RCV] orbs, makes [RCV] orbs beneficial for all characters, boosts ATK of all characters by 2x-3.75x depending on the amount healed in the last turn."},{"key":"llbbase","label":"LLB Base Captain Ability","text":"Reduces HP of all characters by 20%, reduces damage received by 15%, boosts ATK of all characters by 4.5x-5.25x depending on the amount healed in the last turn and boosts chances of getting [RCV] orbs, makes [RCV] orbs beneficial for all characters, characters who attack with a Type advantage will gain a [RCV] orb after attacking and allows HP Overfill up to 2x MAX HP."}],"captainNotes":"The range of ATK boost is from 2x to 3.75x. The exact boost is calculated as 2 + <HP recovered in the previous turn> * 0.000175 and maxes at 10k HP healed. This ignores your max HP, so it doesn''t stop counting if you over-heal.. #{beneficial}","specialName":"Kingdom Come","specialText":"Deals 25x Excess Healing done before the special is activated in Typeless damage to all enemies.. Deals 30x Excess Healing done before the special is activated in Typeless damage to all enemies, boosts Orb Effects of Shooter and Striker characters by 2.25x for 1 turn and adds 1.1x to Chain multiplier for 1 turn. If your crew has Orb Amplification when the special is activated, increases boost effects of Orb Amplification buffs by +0.3x. If your crew has Normal Attack Only when the special is activated, reduces Ship Bind and Paralysis duration by 5 turns.","specialNotes":"The Excess Healing is counted from the last time the special is used and accumulates when you heal more than your maximum HP. For example, if you are at max HP and you heal 1,000 HP, you will add 25k damage to the special. The amount of damage possible caps at 5,000,000 damage (9,000,000 with LLB).","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kami eneru","eneru"],"builderAbilities":[],"sailorAbilities":["Makes [RCV] orbs beneficial for all characters. Boosts amount healed from [RCV] orbs by 300 each"],"sailorNotes":"#{beneficial}","limitBreak":[{"description":"Boosts base HP by 5"},{"description":"Boosts base HP by 10"},{"description":"Boosts base HP by 15"},{"description":"Acquire Potential 1: [STR] Damage Reduction"},{"description":"Boosts base ATK by 5"},{"description":"Boosts base ATK by 5"},{"description":"Boosts base ATK by 10"},{"description":"Acquire Sailor Ability 1: Makes [RCV] orbs beneficial for all characters"},{"description":"Boosts base HP by 20"},{"description":"Boosts base HP by 30"},{"description":"Boosts base HP by 30"},{"description":"Boosts base ATK by 10"},{"description":"Boosts base ATK by 20"},{"description":"Boosts base ATK by 20"},{"description":"Acquire Potential 2: Reduce Slot Bind duration"},{"description":"Boosts base HP by 30"},{"description":"Boosts base HP by 30"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Boosts base ATK by 20"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 50"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Boosts base HP by 50"},{"description":"Boosts base ATK by 30"},{"description":"Boosts base ATK by 30"},{"description":"Acquire Sailor Ability 2: Boosts amount healed from [RCV] orbs by 300 each"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base RCV by 30"},{"description":"Acquire Potential 3: Reduce No Healing duration"},{"description":"LOCKED WITH KEY"},{"description":"Boosts base HP by 25"},{"description":"Boosts base ATK by 50"},{"description":"Boosts base HP by 25"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base RCV by 50"},{"description":"Boosts base ATK by 100"}],"potentialAbilities":[{"Name":"[STR] Damage Reduction","description":["Reduces damage taken from [STR] characters by 1%","Reduces damage taken from [STR] characters by 2%","Reduces damage taken from [STR] characters by 3%","Reduces damage taken from [STR] characters by 4%","Reduces damage taken from [STR] characters by 5%"]},{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 1 turn on this character","Reduces Slot Bind duration by 3 turns on this character","Reduces Slot Bind duration by 5 turns on this character","Reduces Slot Bind duration by 7 turns on this character","Reduces Slot Bind duration by 10 turns on this character"]},{"Name":"Reduce No Healing duration","description":["Reduces No Healing duration by 1 turn","Reduces No Healing duration by 3 turns","Reduces No Healing duration by 5 turns","Reduces No Healing duration by 7 turns","Reduces No Healing duration by 10 turns"]}],"supportData":[{"supportedCharactersText":"[QCK] characters","levelDescriptions":["Reduces damage received from [STR] characters by 1%. Adds 5% of this character''s base RCV to the supported character''s base RCV","Reduces damage received from [STR] characters by 2%. Adds 8% of this character''s base RCV to the supported character''s base RCV","Reduces damage received from [STR] characters by 3%. Adds 12% of this character''s base RCV to the supported character''s base RCV","Reduces damage received from [STR] characters by 4%. Adds 15% of this character''s base RCV to the supported character''s base RCV","Reduces damage received from [STR] characters by 5%. Adds 20% of this character''s base RCV to the supported character''s base RCV"]}],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"ability":[{"effects":[{"attributes":["HP"],"effect":"buff","level":2,"targeting":{"targets":["crew"]}},{"attributes":["DEF"],"effect":"buff","level":2,"targeting":{"count":1,"priority":"highest","stat":"RCV","targets":["crew"]}}]},{"effects":[{"override":{"level":3}},{}]},{"effects":[{"override":{"level":4}},{}]},{"effects":[{"override":{"level":5}},{}]},{"effects":[{"override":{"level":6}},{}]}],"gpability":[{"effects":[{"attributes":["ATK"],"effect":"buff","level":1,"targeting":{"targets":["crew"]}},{"attributes":["HP","SPD"],"effect":"buff","level":1,"targeting":{"targets":["crew"]}}]},{"effects":[{"override":{"level":1}},{"override":{"level":2}}]},{"effects":[{"override":{"level":2}},{"override":{"level":2}}]},{"effects":[{"override":{"level":2}},{"override":{"level":3}}]},{"effects":[{"override":{"level":3}},{"override":{"level":3}}]}],"gpspecial":[{"uses":2,"effects":[{"amount":500,"effect":"damage","targeting":{"targets":["enemies"]},"type":"fixed"}]},{"uses":2,"effects":[{"override":{"amount":625}}]},{"uses":2,"effects":[{"override":{"amount":750}}]},{"uses":2,"effects":[{"override":{"amount":875}}]},{"uses":2,"effects":[{"override":{"amount":1000}}]}],"gpcondition":[{"count":2,"type":"defeat","team":"enemies"}],"id":2232,"pattern":[{"action":"attack","type":"Normal"},{"action":"attack","type":"Normal"},{"action":"heal","area":"Self","level":3}],"llbability":[{"effects":[{"attributes":["HP"],"effect":"buff","level":3,"targeting":{"targets":["crew"]}},{"attributes":["DEF"],"effect":"buff","level":3,"targeting":{"count":1,"priority":"highest","stat":"RCV","targets":["crew"]}}]},{"effects":[{"override":{"level":4}},{}]},{"effects":[{"override":{"level":5}},{}]},{"effects":[{"override":{"level":6}},{}]},{"effects":[{"override":{"level":7}},{}]}],"llbresilience":[{"attribute":"Paralysis","chance":100,"type":"debuff"},{"attribut