      INSERT INTO character_details (character_id, detail_json)
      VALUES (2322, '{"characterId":2322,"captainAbility":"Boosts ATK of Fighter and Powerhouse characters by 2x. Deals 2x the damage taken from enemies in the previous turn in Typeless damage to all enemies at the end of each turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Fighter and Powerhouse characters by 2x. Deals 2x the damage taken from enemies in the previous turn in Typeless damage to all enemies at the end of each turn."}],"captainNotes":null,"specialName":"Scorching Fist","specialText":"Removes any Orb Rate Up and Orb Rate Down Buffs, changes [STR], [DEX], [QCK], [PSY] and [INT] orbs into [EMPTY] orbs, deals 7x-350x character''s ATK in [STR] damage to one enemy, depending on number of [STR], [DEX], [QCK], [PSY] or [INT] slots emptied. Changes all orbs into Matching orbs. If enemies have All Debuff Protection, Delay Debuff Protection or Poison Debuff Protection when the special is activated, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 1.75x for 1 turn. If during that turn you score 4 PERFECT hits, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 1.75x for 2 turns in the following turn.","specialNotes":"The exact multiplier used is chosen based on the number of [STR], [DEX], [QCK], [PSY] or [INT] orbs consumed: 0 orbs - 7x ATK; 1 orb - 52.5x ATK; 2 orbs - 105x ATK; 3 orbs - 157.5x ATK; 4 orbs - 210x ATK; 5 orbs - 262.5x ATK; 6 orbs - 350x ATK.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["charlotte oven","oven"],"builderAbilities":[],"sailorAbilities":["Boosts base ATK of [STR], [DEX] and [QCK] characters by 40"],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":null}');
    

