      INSERT INTO character_details (character_id, detail_json)
      VALUES (2434, '{"characterId":2434,"captainAbility":"Boosts ATK of Free Spirit characters by 3x-3.75x based on the timing of the attack of the previous unit in the chain and recovers 1,200 HP at the end of each turn.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Boosts ATK of Free Spirit characters by 3x-3.75x based on the timing of the attack of the previous unit in the chain and recovers 1,200 HP at the end of each turn."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Boosts ATK of Free Spirit characters by 3.25x-3.75x based on the timing of the attack of the previous unit in the chain, boosts HP of Free Spirit characters by 1.3x, and recovers 1,200 HP at the end of each turn."},{"key":"llbbase","label":"LLB Base Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Free Spirit characters by 4.25x-5x based on the timing of the attack of the previous unit in the chain, boosts HP of Free Spirit characters by 1.35x and recovers 1,500 HP at the end of each turn."},{"key":"llblevel1","label":"LLB Level 1 Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Free Spirit characters by 4.5x-5.25x based on the timing of the attack of the previous unit in the chain, boosts HP of Free Spirit characters by 1.35x, and recovers 2,000 HP at the end of each turn. Once per an adventure, if your crew obtains ATK UP effect, activates \"Love-Love Combination\" in the following turn."}],"captainNotes":"A hit below Good or a Miss will boost the ATK of the next unit by 3x, a Good hit by 3.25x, a Great hit by 3.5x and a PERFECT hit by 3.75x. This bonus is applied only to Free Spirit characters.","specialName":"Love-Love Combination","specialText":"Deals 12 hits of 25,000 Fixed damage to random enemies, delays all enemies by 1 turn and boosts the Color Affinity of Free Spirit characters by 2x for 1 turn.. Deals 12 hits of 30,000 Fixed damage to random enemies. If enemies are delayed or inflicted with Melo-Melo after receiving damage from this special, reduces enemies'' Threshold Damage Reduction and Percent Damage Reduction duration by 6 turns, by 3 turns otherwise. Delays all enemies by 1 turn and boosts the Color Affinity of Free Spirit characters by 2.25x for 2 turns. If your crew has Monkey D. Luffy as a member or supporting this character when the special is activated, boosts ATK against delayed enemies by 1.75x for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["boa hancock","hancock"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_damage_reduction","label":"Remove Damage Reduction","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"}],"sailorAbilities":["Makes [STR], [QCK], [DEX], [PSY] and [INT] orbs beneficial for this character if your Captain is a Free Spirit character"],"sailorNotes":"#{beneficial}","limitBreak":[{"description":"Boosts base RCV by 10"},{"description":"Boosts base HP by 30"},{"description":"Boosts base ATK by 20"},{"description":"Acquire Potential 1: Pinch Healing"},{"description":"Boosts base RCV by 10"},{"description":"Boosts base HP by 40"},{"description":"Boosts base ATK by 20"},{"description":"Boosts base RCV by 10"},{"description":"Boosts base HP by 50"},{"description":"Boosts base ATK by 20"},{"description":"Acquire Sailor Ability 1: Makes [STR], [QCK], [DEX], [PSY] and [INT] orbs beneficial for this character if your Captain is a Free Spirit character"},{"description":"Boosts base RCV by 15"},{"description":"Boosts base HP by 50"},{"description":"Boosts base ATK by 25"},{"description":"Acquire Potential 2: Barrier Penetration"},{"description":"Boosts base RCV by 15"},{"description":"Boosts base HP by 50"},{"description":"Boosts base ATK by 25"},{"description":"Boosts base RCV by 15"},{"description":"Boosts base HP by 60"},{"description":"Boosts base ATK by 25"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Boosts base RCV by 15"},{"description":"Boosts base HP by 70"},{"description":"Boosts base ATK by 25"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base HP by 80"},{"description":"Boosts base ATK by 30"},{"description":"Boosts base HP by 90"},{"description":"Acquire Potential 3: Reduce No Healing duration"},{"description":"LOCKED WITH KEY"},{"description":"Boosts base HP by 100"},{"description":"Boosts base RCV by 25"},{"description":"Boosts base RCV by 50"},{"description":"Boosts base ATK by 100"},{"description":"Boosts base HP by 100"},{"description":"Boosts base HP by 150"},{"description":"Acquire new Captain Ability: Boosts ATK of Free Spirit characters by 3.25x-3.75x based on the timing of the attack of the previous unit in the chain, boosts HP of Free Spirit characters by 1.3x, and recovers 1,200 HP at the end of each turn."},{"description":"Reduce base Special Cooldown by 2 turns"},{"description":"Boosts base ATK by 100"}],"potentialAbilities":[{"Name":"Pinch Healing","description":["If HP is below 10% at the start of the turn, recovers 2x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 15% at the start of the turn, recovers 2x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 20% at the start of the turn, recovers 2x this character''s RCV at the end of the turn for each time you hit a PERFECT with this cha