      INSERT INTO character_details (character_id, detail_json)
      VALUES (3279, '{"characterId":3279,"captainAbility":"Boosts ATK of Driven and Powerhouse characters by 4x, their HP by 1.75x, reduces RCV of Driven and Powerhouse characters by 50%, increases damage received by 1.5x and reduces Special Cooldown of this character by 2 turns after each turn you take damage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with an ATK boost that will overwrite ATK boosts in the same special: Boosts ATK of Driven and Powerhouse characters by 2x for 1 turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of Driven and Powerhouse characters by 4x, their HP by 1.75x, reduces RCV of Driven and Powerhouse characters by 50%, increases damage received by 1.5x and reduces Special Cooldown of this character by 2 turns after each turn you take damage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with an ATK boost that will overwrite ATK boosts in the same special: Boosts ATK of Driven and Powerhouse characters by 2x for 1 turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of Driven and Powerhouse characters by 4x, their HP by 1.75x, reduces RCV of Driven and Powerhouse characters by 50%, increases damage received by 1.5x and deals 10% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies at the start of every stage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with an ATK boost that will overwrite ATK boosts in the same special: Boosts ATK of Driven and Powerhouse characters by 2x for 1 turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of Driven and Powerhouse characters by 5x, their HP by 1.75x, reduces Special Cooldown of this character by 2 turns after each turn you take damage and deals 10% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies at the start of every stage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with an ATK boost that will overwrite ATK boosts in the same special: Boosts ATK of Driven and Powerhouse characters by 2x for 1 turn."}],"captainNotes":null,"specialName":"Tremendous Dismay of Darkness and Earthquakes","specialText":"Adds 1.0x to Chain multiplier for 1 turn and becomes Blackbeard, Two Overwhelming Abilities for 3-8 turns depending on the total Damage Taken before the special is activated. If your Captain is a Powerhouse or Driven character, increases duration of any ATK boosting buffs and Orb Amplification buffs by 1 turn.","specialNotes":"0 damage: 3 turns<br>? damage: 4 turns<br>? damage: 5 turns<br>? damage: 6 turns<br>? damage: 7 turns<br>50,000 damage: 8 turns","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["marshall d. teach","teach"],"builderAbilities":[{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK of Driven characters by 75. Boosts base ATK of Powerhouse characters by 75. Boosts base ATK of Driven and Powerhouse characters by 125"],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":"Removes Despair and Silence duration completely on this character and changes the orb, including [BLOCK] orbs, of this character into a Matching orb.","vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":3280,"id":3279}}');
    

