      INSERT INTO character_details (character_id, detail_json)
      VALUES (3550, '{"characterId":3550,"captainAbility":"Boosts ATK of Driven characters by 4.5x if they have a beneficial orb, by 3.75x otherwise and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Boosts ATK of Driven characters by 4.5x if they have a beneficial orb, by 3.75x otherwise and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight. If they have a beneficial orb, boosts ATK of Driven characters by 4.75x, by 4x otherwise, and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."},{"key":"llbbase","label":"LLB Base Captain Ability","text":"Boosts ATK of Driven characters by 4.75x, by 5x instead if they have a beneficial orb, boosts HP of Driven characters by 1.4x, lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."},{"key":"llblevel1","label":"LLB Level 1 Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight. Boosts ATK of Driven characters by 5x, by 5.25x instead if they have a beneficial orb, boosts HP of Driven characters by 1.4x, lowers chances of getting [STR] orbs, makes [DEX] and [QCK] orbs beneficial for Driven characters and reduces Despair duration by 5 turns."}],"captainNotes":"#{beneficial}","specialName":"Life-Stealing Thousand Arrows: Flapping Thread","specialText":"Deals 2.5x the damage dealt in Overkill Damage in the previous turn in Typeless damage to all enemies. If your crew has Normal Attack Only when the special is activated, boosts ATK of Driven characters by 2.5x for 1 turn and makes [PSY] and [INT] orbs beneficial for Driven characters for 1 turn.. Deals 2.5x the damage dealt in Overkill Damage in the previous turn in Typeless damage to all enemies. If your Captain is a Driven character, reduces enemies'' Percent Damage Reduction and Increased Defense duration by 6 turns. If your crew has Normal Attack Only when the special is activated, boosts ATK of Driven characters by 2.5x for 1 turn and makes [PSY] and [INT] orbs beneficial for Driven characters for 1 turn.","specialNotes":"Overkill Damage is damage dealt over the enemies'' current HP with normal attacks that killed them. For example, dealing 2,100,000 damage to an enemy with 1,000,000 HP will count as 1,100,000 Overkill Damage. This stacks for each enemy killed in the previous turn. The Overkill Damage Counter caps out at 999,999,999 damage.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["donquixote doflamingo","doflamingo"],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":["Makes [QCK] orbs beneficial for this character. Makes [DEX] orbs beneficial for Driven characters"],"sailorNotes":"#{beneficial}","limitBreak":[{"description":"Boosts base ATK by 10"},{"description":"Boosts base ATK by 15"},{"description":"Boosts base ATK by 20"},{"description":"Acquire Potential 1: [QCK] Damage Reduction"},{"description":"Boosts base RCV by 5"},{"description":"Boosts base RCV by 10"},{"description":"Boosts base RCV by 15"},{"description":"Acquire Sailor Ability 1: Makes [QCK] orbs beneficial for this character"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base RCV by 25"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base RCV by 35"},{"description":"Boosts base RCV by 40"},{"description":"Boosts base RCV by 50"},{"description":"Boosts base HP by 20"},{"description":"Acquire Potential 2: Reduce No Healing duration"},{"description":"Boosts base HP by 25"},{"description":"Boosts base HP by 30"},{"description":"Boosts base HP by 35"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 45"},{"description":"Boosts base HP by 50"},{"description":"Boosts base HP by 55"},{"description":"Boosts base HP by 60"},{"description":"Boosts base HP by 65"},{"description":"Boosts base HP by 75"},{"description":"Boosts base ATK by 55"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Acquire Sailor Ability 2: Makes [DEX] orbs beneficial for Driven characters"},{"description":"Acquire Potential 3: Reduce Slot Bind duration"},{"description":"LOCKED WITH KEY"},{"description":"Boosts base HP by 100"},{"description":"Boosts base HP by 100"},{"description":"Boosts base RCV by 50"},{"description":"Boosts base HP by 150"},{"description":"Boosts base ATK by 100"},{"description":"Boosts base ATK by 100"},{"description":"Acquire new Captain Ability: Reduces Special Cooldown of all characters by 1 turn at the start of the fight. If they have a beneficial orb, boosts ATK of Driven characters by 4.75x, by 4x otherwise, and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."},{"description":"Reduce base Special Cooldown by 3 turns"},{"description":"Boosts base HP by 150"}],"potentialAbilities":[{"Name":"[QCK] Damage Reduction","description":["Reduces damage taken from [QCK] characters by 1%","Reduces damage taken from [QCK] characters by 2%","Reduces damage taken from [QCK] characters by 3%","Reduces damage taken from [QCK] characters by 4%","Reduces damage taken from [QCK] characters by 5%"]},{"Name":"Reduce No Healing duration","description":["Reduces No Healing 