      INSERT INTO character_details (character_id, detail_json)
      VALUES (3640, '{"characterId":3640,"captainAbility":"Boosts ATK of Driven and Powerhouse characters by 4.75x, by 5.25x instead if they have a beneficial orb, their HP by 1.5x and makes [INT] and [TND] orbs beneficial for Driven and Powerhouse characters. If a crew member uses a special with a base ATK UP or End of Turn Healing buff, replaces those buffs with an base ATK boost that will overwrite base ATK boosts in the same special: Boosts base ATK of Driven and Powerhouse characters by 1,250 for 1 turn. If a crew member uses a special with a Percent Damage Reduction or Chain Addition buff, replaces those buffs with an Chain Addition boost that will overwrite Chain Addition boosts in the same special: Adds 1.4x to Chain multiplier for 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Driven and Powerhouse characters by 4.75x, by 5.25x instead if they have a beneficial orb, their HP by 1.5x and makes [INT] and [TND] orbs beneficial for Driven and Powerhouse characters. If a crew member uses a special with a base ATK UP or End of Turn Healing buff, replaces those buffs with an base ATK boost that will overwrite base ATK boosts in the same special: Boosts base ATK of Driven and Powerhouse characters by 1,250 for 1 turn. If a crew member uses a special with a Percent Damage Reduction or Chain Addition buff, replaces those buffs with an Chain Addition boost that will overwrite Chain Addition boosts in the same special: Adds 1.4x to Chain multiplier for 1 turn."}],"captainNotes":null,"specialName":"Ground-Shaking Tremors","specialText":"Deals 20% of enemies'' current HP in True damage to all enemies, reduces Bind duration by 10 turns. If during that turn you score 2 PERFECT hits, sets Chain Boundaries to 2.75x and 35.0x for 1 turn in the following turn. If your Captain is a Driven or Powerhouse character, sets Chain Boundaries to 3.0x and 40.0x for 1 turn, sets Chain Boundaries to 2.5x and 35.0x for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["marshall d. teach","teach"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":3641,"id":3640}}');
    

