      INSERT INTO character_details (character_id, detail_json)
      VALUES (3877, '{"characterId":3877,"captainAbility":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts ATK of [STR] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs and reduces Bind duration by 10 turns. If this character defeat an enemy, reduces Swap Cooldown of this character by 1.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts ATK of [STR] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs and reduces Bind duration by 10 turns. If this character defeat an enemy, reduces Swap Cooldown of this character by 1."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Striker and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts RCV of all characters by 1.2x, boosts ATK of [DEX] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, reduces damage received by 25% and reduces Bind duration by 10 turns. After each turn you take damage, reduces Swap Cooldown of this character by 1."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter, Striker and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts RCV of all characters by 1.2x, boosts ATK of [STR], [DEX], [QCK] and Free Spirit characters by 6x, boosts ATK of all other characters by 5.25x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs, reduces damage received by 30% and reduces Bind duration by 10 turns."}],"captainNotes":null,"specialName":"Club and Fists Beatdown","specialText":"Reduces Special Cooldown of all characters by 1 turn, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 3x for 1 turn, reduces damage received by 60% for 1 turn, changes orbs of adjacent characters into [RCV] orbs, inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn and becomes Luffy & Yamato for 3 turns. If your crew has Orb Amplification and Percent Damage Reduction when the special is activated, increases duration of any ATK UP, Orb Amplification and Chain Lock/Limit/Boundary buffs/debuffs by 1 turn.. Reduces Special Cooldown of all characters by 2 turns, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 3.25x for 2 turns, reduces damage received by 80% for 1 turn, changes orbs of adjacent characters into [WANO] orbs, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2x for 1 turn and becomes Luffy & Yamato for 3 turns. If your crew has Orb Amplification and Percent Damage Reduction when the special is activated, increases duration of any ATK UP, Orb Amplification and Chain Lock/Limit/Boundary buffs/debuffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["luffy & yamato","luffy","yamato"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":["Makes [RCV] and [TND] orbs beneficial for all characters. Boosts base ATK of all characters by 100"],"sailorNotes":null,"limitBreak":[{"description":"Boosts base ATK by 10"},{"description":"Boosts base ATK by 10"},{"description":"Boosts base HP by 20"},{"description":"Acquire Potential 1: Pinch Healing"},{"description":"Boosts base ATK by 10"},{"description":"Boosts base ATK by 10"},{"description":"Boosts base HP by 20"},{"description":"Boosts base HP by 20"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base HP by 30"},{"description":"Boosts base HP by 30"},{"description":"Boosts base ATK by 20"},{"description":"Boosts base ATK by 20"},{"description":"Boosts base ATK by 20"},{"description":"Acquire Potential 2: Reduce Slot Bind duration"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Boosts base RCV by 40"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 40"},{"description":"Boosts base HP by 50"},{"description":"Boosts base ATK by 30"},{"description":"Boosts base ATK by 30"},{"description":"Boosts base RCV by 40"},{"description":"Acquire Sailor Ability 1: Makes [RCV] and [TND] orbs beneficial for all characters"},{"description":"Boosts base HP by 60"},{"description":"Boosts base HP by 70"},{"description":"Boosts base HP by 80"},{"description":"Boosts base ATK by 40"},{"description":"Acquire Potential 3: Last Tap"},{"description":"LOCKED WITH KEY"},{"description":"Boosts base ATK by 50"},{"description":"Boosts base ATK by 50"},{"description":"Boosts base HP by 100"},{"description":"Boosts base HP by 150"},{"description":"Boosts base RCV by 20"},{"description":"Boosts base HP by 250"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base ATK by 100"},{"description":"Reduce base Special Cooldown by 1 turn"}],"potentialAbilities":[{"Name":"Pinch Healing","description":["If HP is below 10% at the start of the turn, recovers 1x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 20% at the start of the turn, recovers 1x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 30% at the start of the turn, recovers 1x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 40% at the start of the turn, recovers 1.5x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character","If HP is below 50% at the start of the turn, recovers 1.5x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character"]},{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 1 turn on this character","Reduces Slot Bind duration by 3 turns on this character","Reduces Slot Bind duration by 5 turns on this character","Reduces Slot Bind duration by 7 turns on this character","Reduces Slot Bind duration by 10 turns on this character"]},{"Name":"Last Tap","description":["Last Tap Ability Lv.1","Last Tap Ability Lv.2","Last Tap Ability Lv.3","Last Tap Ability Lv.4","Last Tap Ability Lv.5"]}],"supportData":[],"swapData":{"base":"Removes Despair, Paralysis and Slot Bind duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a [WANO] orb and boosts Color Affinity of Free Spirit characters by 1.5x, allowing override, for 1 turn.","super":"Removes Despair, Paralysis and Slot Bind duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a [WANO] orb, boosts Color Affinity of Free Spirit characters by 2.5x for 1 turn and becomes Luffy & Yamato for 3 turns.","superTurns":8},"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":3878,"id":3877}}');
    

