      INSERT INTO character_details (character_id, detail_json)
      VALUES (3904, '{"characterId":3904,"captainAbility":"Boosts ATK of all characters by 5x, by 5.5x instead if they have a [RCV], [TND], [WANO], [EMPTY], [G] or [RAINBOW] orb and makes [RCV] and [TND] orbs beneficial for all characters. Characters who attack with a Type advantage will gain a [RCV] orb after attacking. Wooo-Hoo!!!","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 5x, by 5.5x instead if they have a [RCV], [TND], [WANO], [EMPTY], [G] or [RAINBOW] orb and makes [RCV] and [TND] orbs beneficial for all characters. Characters who attack with a Type advantage will gain a [RCV] orb after attacking. Wooo-Hoo!!!"}],"captainNotes":null,"specialName":"Face Spectrum Galaxy Wink","specialText":"Reduces Special Cooldown of top row characters by 3 turns. If your crew has Chain Lock when the special is activated, increases duration of any Chain Lock/Limit/Boundary buffs/debuffs by 1 turn. If your Captain is a Fighter or Slasher character when the special is activated, boosts ATK of all characters by 2.25x for 3 turns. If your Captain is a Shooter or Striker character when the special is activated, boosts Orb Effects of all characters by 2.25x for 3 turns. If your Captain is a Free Spirit or Powerhouse character when the special is activated, boosts Color Affinity of all characters by 2.25x for 3 turns. If your Captain is a Cerebral or Driven character when the special is activated, adds 1.3x to Chain multiplier for 3 turns. If your Captain is a [STR], [DEX] or [QCK] character when the special is activated, reduces enemies'' Increased Defense and Percent Damage Reduction duration by 6 turns. If your Captain is a [PSY] or [INT] character when the special is activated, reduces Bind and Despair duration by 6 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["emporio ivankov","ivankov"],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_damage_reduction","label":"Remove Damage Reduction","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_bind","label":"Remove Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":3905,"id":3904}}');
    

