      INSERT INTO character_details (character_id, detail_json)
      VALUES (3916, '{"characterId":3916,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Driven and Cerebral characters by 5x, boosts HP of Driven and Cerebral characters by 1.2x, makes [DEX] and [QCK] orbs beneficial for all characters and lowers chances of getting [STR] and [PSY] orbs. If this character has a [DEX] or [INT] orb and you attack with this character, reduces enemies'' Driven Resistance by -10% for 1 turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Driven and Cerebral characters by 5x, boosts HP of Driven and Cerebral characters by 1.2x, makes [DEX] and [QCK] orbs beneficial for all characters and lowers chances of getting [STR] and [PSY] orbs. If this character has a [DEX] or [INT] orb and you attack with this character, reduces enemies'' Driven Resistance by -10% for 1 turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Driven and Cerebral characters by 5x, boosts HP of Driven and Cerebral characters by 1.2x, makes [DEX] and [QCK] orbs beneficial for all characters and lowers chances of getting [STR] and [PSY] orbs. If this character has a [QCK] or [INT] orb and you attack with this character, reduces enemies'' Cerebral Resistance by -10% for 1 turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Driven and Cerebral characters by 5.25x, by 5.75x instead if they have a beneficial orb, boosts HP of Driven and Cerebral characters by 1.2x, makes [DEX] and [QCK] orbs beneficial for all characters and lowers chances of getting [STR] and [PSY] orbs. If this character has a [DEX], [QCK] or [INT] orb and you attack with this character, reduces enemies'' Driven and Cerebral Resistance by -20% for 1 turn."}],"captainNotes":null,"specialName":"Sand and Thread Pincer Attack","specialText":"Boosts ATK of Driven and Cerebral characters by 2.75x for 1 turn and becomes Doflamingo & Crocodile for 1 turn. Increases boost effects of 4 selected buffs depending on buffs selected. In exchange, reduces crew''s current HP by 25% crew''s MAX HP per selected buff.. <b>Buff Enhancements:</b><ul><li>Increases boost effects of ATK UP by +0.25x</li><li>Increases boost effects of Orb Amplification buffs by +0.25x</li><li>Increases boost effects of Color Affinity buffs by +0.25x</li><li>Increases boost effects of Status ATK buffs by +0.25x</li><li>Increases boost effects of Chain Lock buffs by +0.25x</li><li>Increases boost effects of Chain Addition buffs by +0.5x</li><li>Increases boost effects of Chain Multiplication buffs by +0.2x</li><li>Increases boost effects of Base ATK Boost buffs by +400</li></ul>","specialNotes":"Requires exactly 25% MAX HP per selected buff, but if HP would be reduced to 0, 1 HP is left instead.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["doflamingo & crocodile","doflamingo","crocodile"],"builderAbilities":[],"sailorAbilities":["Boosts base ATK of Driven and Cerebral characters by 100"],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":{"base":"Changes orb of this character into a Matching orb, recovers 5% of crew''s MAX HP, reduces Silence and Bind duration by 1 turn and makes [INT] orbs beneficial for all characters for 1 turn.","super":"Changes orb of this character into an [INT] orb, recovers 10% of crew''s MAX HP, reduces Silence and Bind duration by 3 turns and makes [INT] orbs beneficial for all characters for 1 turn","superTurns":4},"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":3917,"id":3916}}');
    

