      INSERT INTO character_details (character_id, detail_json)
      VALUES (3985, '{"characterId":3985,"captainAbility":"Boosts ATK of Driven and Powerhouse characters by 4.5x, by 5.25x instead if you use \"Glorious Death of the Kurozumi Clan, Kazenbo\" in this turn and boosts HP of all characters by 1.25x. 2 times per adventure, every turn Damage Taken exceeds 30,000, activates \"Glorious Death of the Kurozumi Clan, Kazenbo\" and reset stacks.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Driven and Powerhouse characters by 4.5x, by 5.25x instead if you use \"Glorious Death of the Kurozumi Clan, Kazenbo\" in this turn and boosts HP of all characters by 1.25x. 2 times per adventure, every turn Damage Taken exceeds 30,000, activates \"Glorious Death of the Kurozumi Clan, Kazenbo\" and reset stacks."}],"captainNotes":null,"specialName":"Glorious Death of the Kurozumi Clan, Kazenbo","specialText":"If your crew has ATK UP with a multiplier of 3x or more when the special is activated, increases duration of any Orb Amplification buffs by 1 turn. If your crew has Orb Amplification with a multiplier of 3x or more when the special is activated, increases duration of any Orb Amplification buffs by 1 turn. If your Captain is a Driven or Powerhouse character, increases boost effects of ATK UP buffs to 3x and increases boost effects of Orb Amplification buffs to 3x. If enemies are inflicted with Burn when the special is activated, makes [DEX] orbs beneficial for all characters for 2 turns, changes all orbs into [DEX] orbs and boosts base ATK of [STR], Driven and Powerhouse characters by 1,250 for 2 turns, inflicts all enemies with Burn that will deal 150x enemies'' ATK in damage for 3 turns otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kurozumi kanjuro","kanjuro"],"builderAbilities":[],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[