      INSERT INTO character_details (character_id, detail_json)
      VALUES (4004, '{"characterId":4004,"captainAbility":"Boosts ATK of all characters by 3.25x and gives chance of duplicating a drop upon completion of the island.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 3.25x and gives chance of duplicating a drop upon completion of the island."}],"captainNotes":null,"specialName":"Betting for Freedom","specialText":"Applies various effects depending on the character''s Support Character''s type, Captain''s type, character''s orb, and current HP percentage when the Special is activated. . <table class=\"table table-striped-column abilities\"><colgroup><col style=\"width: 10%\"><col style=\"width: 10%\"><col style=\"width: 80%\"></colgroup><thead><tr><th></th><th>Condition</th><th>Effect</th></tr></thead><tbody><tr><td rowspan=\"3\">Captain Type</td><td>[STR] or [DEX]</td><td>Deals 80x character''s ATK in [QCK] damage to all enemies at the end of the turn for 3 turns</td></tr><tr><td>[QCK]</td><td>Reduces Special Cooldown of all characters by 2 turns.</td></tr><tr><td>[PSY] or [INT]</td><td>Reduces Swap Cooldown and VS Special Cooldown of all characters by 2 turns.</td></tr><tr><td rowspan=\"4\">Character''s Orb</td><td>[STR], [DEX], [QCK], [PSY] or [INT]</td><td>Reduces enemies'' Corresponding Type Resistance by -20% for 1 turn.</td></tr><tr><td>[RCV] or [TND]</td><td>Locks all orbs for 1 turn and adds 1.1x to Chain multiplier for 1 turn.</td></tr><tr><td>[G] or [RAINBOW]</td><td>Reduces enemies'' [STR], [DEX], [QCK], [PSY] and [INT] Resistance by -20% for 1 turn and barriers all character''s orbs for 1 GREAT hit.</td></tr><tr><td>[SEMLA], [BLOCK] or [SUPERBLOCK]</td><td>Increases damage received by 2x for 3 turns.</td></tr><tr><td rowspan=\"4\">Percent HP</td><td>100%-80.01%</td><td>Reduces damage received by 80% for 1 turn.</td></tr><tr><td>80%-50.01%</td><td>Recovers 20,000 HP.</td></tr><tr><td>50%-10.01%</td><td>Reduces damage received by 100% for 1 turn.</td> </tr><tr><td><=10%</td><td>Recovers all missing HP.</td></tr><tr><td rowspan=\"6\">Support Character Type</td><td>[STR]</td><td>Boosts ATK of all characters by 2x for 3 turns.</td></tr><tr><td>[DEX]</td><td>Boosts ATK of all characters by 2.25x for 2 turns.</td></tr><tr><td>[QCK]</td><td>Boosts ATK of all characters by 2.5x for 1 turn.</td></tr><tr><td>[PSY]</td><td>Increases boost effects of ATK UP buffs by +0.3x.</td></tr><tr><td>[INT]</td><td>Increases boost effects of ATK UP buffs to 2.5x.</td></tr><tr><td>None</td><td>Boosts Orb Effects of all characters by 2.25x for 2 turns.</td></tr></tbody></table>","specialNotes":"The following orbs have no effects: [WANO], [EMPTY], [BOMB]. Other orbs are untested.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["raise max","max"],"builderAbilities":[{"key":"extra_drop_any","label":"Any Extra Drop","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":["Restores Special Cooldown of this character by 2 turns when it is rewinded. Reduces Silence duration by 6 turns on this character"],"sailorNotes":null,"limitBreak":[{"description":"Boosts base HP by 10"},{"description":"Boosts base HP by 20"},{"description":"Boosts base RCV by 10"},{"description":"Acquire Potential 1: Cooldown Reduction"},{"description":"Boosts base ATK by 40"},{"description":"Boosts base RCV by 10"},{"description":"Boosts base ATK by 50"},{"description":"Acquire 1 additional Socket slot"},{"description":"Boosts base HP by 30"},{"description":"Boosts base RCV by 30"},{"description":"Boosts base ATK by 60"},{"description":"Acquire Sailor Ability 1: Reduces Silence duration by 6 turns on this character"},{"description":"Boosts base HP by 40"},{"description":"Reduce base Special Cooldown by 1 turn"},{"description":"Acquire Potential 2: Critical Hit"}],"potentialAbilities":[{"Name":"Cooldown Reduction","description":["Reduces character''s Special charge time by 1 turn at the start of the fight","Reduces character''s Special charge time by 2 turns at the start of the fight","Reduces character''s Special charge time by 3 turns at the start of the fight","Reduces character''s Special charge time by 5 turns at the start of the fight","Reduces character''s Special charge time by 7 turns at the start of the fight"]},{"Name":"Critical Hit","description":["If you hit a PERFECT with this character, there is a 40% chance to deal 4% of this character''s attack in extra damage","If you hit a PERFECT with this character, there is a 50% chance to deal 5% of this character''s attack in extra damage","If you hit a PERFECT with this character, there is a 60% chance to deal 6% of this character''s attack in extra damage","If you hit a PERFECT with this character, there is a 70% chance to deal 7% of this character''s attack in extra damage","If you hit a PERFECT with this character, there is a 80% chance to deal 8% of this character''s attack in extra damage"]}],"supportData":[{"supportedCharactersText":"[QCK] characters","levelDescriptions":["Once per adventure, when you reach the final stage, randomizes supported character''s orb.","Once per adventure, when you reach the final stage, changes the orb of the supported character into a [QCK] orb.","Once per adventure, when you reach the final stage, changes the orb of the supported character into a Matching orb.","Once per adventure, when you reach the final stage, changes the orb of the supported character into a [G] orb.","Once per adventure, when you reach the final stage, changes orb of supported character and adjacent characters into [G] orbs."]}],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":null}');
    

