      INSERT INTO character_details (character_id, detail_json)
      VALUES (4057, '{"characterId":4057,"captainAbility":"Nullifies Remove Beneficial Effects and Remove Accumulated Value effects once per adventure, boosts HP of [QCK] and Slasher characters by 1.5x, boosts ATK of [QCK] and Slasher characters by 5.5x, boosts ATK of all other characters by 5x, changes [STR] orbs of Slasher characters into [WANO] orbs and removes Despair duration completely. If you use \"Formidable Onslaught\" on this character, boosts ATK of [QCK] and Slasher characters by 6x and boosts ATK of all other characters by 5.25x instead. When a Critical Hit Enabled Slasher character hits a Critical Hit, reduces enemies'' Slasher Resistance by -6% for 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Nullifies Remove Beneficial Effects and Remove Accumulated Value effects once per adventure, boosts HP of [QCK] and Slasher characters by 1.5x, boosts ATK of [QCK] and Slasher characters by 5.5x, boosts ATK of all other characters by 5x, changes [STR] orbs of Slasher characters into [WANO] orbs and removes Despair duration completely. If you use \"Formidable Onslaught\" on this character, boosts ATK of [QCK] and Slasher characters by 6x and boosts ATK of all other characters by 5.25x instead. When a Critical Hit Enabled Slasher character hits a Critical Hit, reduces enemies'' Slasher Resistance by -6% for 1 turn."}],"captainNotes":null,"specialName":"Formidable Onslaught","specialText":"Deals 1,500,000 Fixed True damage, ignoring Normal Attack Only, to all enemies. If this character''s orb is [WANO] when the special is activated, boosts ATK of [QCK] Slasher characters by 3.25x for 1 turn, boosts ATK of [QCK] and Slasher characters by 2.75x for 1 turn, changes [QCK] orbs into [WANO] orbs for 2 turns, and changes Matching orbs into [QCK] orbs; boosts ATK of [QCK] and Slasher characters by 2.75x for 1 turn otherwise. If there is 10,000,000 or more normal attack damage dealt before this special was activated, boosts Orb Effects of [QCK] Slasher characters by 3x for 3 turns, and boosts Orb Effects of [QCK] and Slasher characters by 2.75x for 3 turns; boosts Orb Effects of [QCK] and Slasher characters by 2.75x for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["roger & oden","roger","oden"],"builderAbilities":[{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":4058,"id":4057}}');
    

