      INSERT INTO character_details (character_id, detail_json)
      VALUES (4071, '{"characterId":4071,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts HP of [QCK] and Free Spirit characters by 1.5x, boosts ATK of [QCK] and Free Spirit characters by 5.25x, by 5.5x instead if they have a beneficial orb, by 5.75x instead if they have a beneficial [TND] or [RAINBOW] orb, boosts ATK of all other characters by 4.75x, makes [STR], [DEX] and [TND] orbs beneficial for all characters, and recovers 5x character''s RCV in HP at the end of each turn. Once per adventure, if HP is below 30%, activates \"Bath Before the Feast\".","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts HP of [QCK] and Free Spirit characters by 1.5x, boosts ATK of [QCK] and Free Spirit characters by 5.25x, by 5.5x instead if they have a beneficial orb, by 5.75x instead if they have a beneficial [TND] or [RAINBOW] orb, boosts ATK of all other characters by 4.75x, makes [STR], [DEX] and [TND] orbs beneficial for all characters, and recovers 5x character''s RCV in HP at the end of each turn. Once per adventure, if HP is below 30%, activates \"Bath Before the Feast\"."}],"captainNotes":null,"specialName":"Bath Before the Feast","specialText":"Reduces Silence, Paralysis and Burn duration by 6 turns, recovers 30,000 HP, and changes orbs, including [BLOCK] orbs, of top and bottom row characters into [RAINBOW] orbs. If your crew has ATK UP when the special is activated, boosts Color Affinity of [QCK] and Free Spirit characters by 2.75x for 1 turn, boosts ATK of [QCK] Free Spirit characters by 3x for 1 turn, and boosts ATK of other [QCK] and Free Spirit characters by 2.75x for 1 turn otherwise.","specialNotes":null,"superSpecialText":"Reduces Silence duration by 6 turns, ignores Delay Debuff Protection and delays all enemies by 1 turn, boosts ATK against delayed enemies by 1.75x for 1 turn, and transforms [QCK] characters into Super [QCK] characters.","superSpecialCriteriaText":"This character must be captain and HP must be below 30% or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Yamato, Kozuki Momonosuke, Otama","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and HP must be below 30% or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Yamato, Kozuki Momonosuke, Otama","requiresCaptain":true,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"options":[{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Sanji","acceptedKeys":["sanji"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},{"label":"Brook","acceptedKeys":["brook"]},{"label":"Jinbe","acceptedKeys":["jinbe"]},{"label":"Yamato","acceptedKeys":["yamato"]},{"label":"Kozuki Momonosuke","acceptedKeys":["kozuki momonosuke","momonosuke"]},{"label":"Otama","acceptedKeys":["otama"]}]}],"hasNonRosterBranches":true,"parserStatus":"mixed"},"partyConflictKeys":["monkey d. luffy","luffy"],"builderAbilities":[{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_burn","label":"Remove Burn","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverage