,"superSpecialCriteria":null,"partyConflictKeys":["jewelry bonney","bonney"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"limitBreak":[],"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superClass":null,"rumbleData":{"basedOn":4084,"id":4083}}');
    

